import { componentAttrs } from "../_utils/component.helper";

/**
 * Content Nester DXP Component -- Server-Side Renderer
 *
 * DXP-edge equivalent of classic Matrix's "Nested Content" component --
 * renders a picked asset's own content inline on the current page. New
 * Content Pages have no native nested-content mechanism; this fills that
 * gap for asset types that still carry raw body content via
 * `resolveUri()`'s `contents` field (confirmed live against a real Squiz
 * DXP backend: populated for a real Bodycopy "Page Contents" asset once it
 * has WYSIWYG body content saved; empty for a Content Page, which has no
 * legacy raw-content storage). See content-nester.spec.md assumption 1.
 */

export default {
  async main(input = {}, info = {}) {
    const debug = `<script>console.log(JSON.parse('${JSON.stringify({input})}'));</script>`
    const { asset = "" } = input;
    let contents;
    try {
      const res = await info.fns.resolveUri(asset);
      contents = res?.data?.contents;
    } catch(err) {
      return "";
    }
    if (!contents) return debug;
    return /*html*/ `
<div ${componentAttrs("content-nester", input)}>
  ${contents}${debug}
</div>`;
  },
};
